/**
 * Load executive intelligence summary for a repository
 * @param {string} repoSource - Data source (mock, noor-canvas, etc.)
 * @param {string} repoPath - Optional repository path override
 * @returns {Promise<Object>} Executive summary data
 */
export async function loadExecutiveIntelligence(repoSource, repoPath = null) {
    try {
        // Construct path based on source
        const dataPath = repoPath || `data/repos/${repoSource}/executive-intelligence.json`;
        
        const response = await fetch(dataPath);
        
        if (!response.ok) {
            console.warn(`Executive intelligence not found for ${repoSource}: ${response.status}`);
            return null;
        }
        
        const data = await response.json();
        
        // Validate data structure
        if (!data.repo_name) {
            console.warn('Invalid executive intelligence format - missing repo_name');
            return null;
        }
        
        return data;
    } catch (error) {
        console.error('Error loading executive intelligence:', error);
        return null;
    }
}

