/**
 * Integrate executive intelligence into dashboard data
 * @param {Object} dashboardData - Main dashboard data object
 * @param {Object} intelligence - Executive intelligence summary
 * @returns {Object} Enhanced dashboard data
 */
export function integrateIntelligence(dashboardData, intelligence) {
    if (!intelligence) {
        return dashboardData;
    }
    
    // Add intelligence data to dashboard
    return {
        ...dashboardData,
        executiveIntelligence: intelligence,
        
        // Enhance existing executive summary with intelligence
        executiveSummary: {
            ...(dashboardData.executiveSummary || {}),
            project_name: intelligence.title || intelligence.repo_name,
            tagline: intelligence.description || '',
            what_it_does: {
                summary: intelligence.purpose || intelligence.description || '',
                key_points: intelligence.capabilities || [],
                source: intelligence.has_readme ? 'readme' : 'generated'
            },
            capabilities: intelligence.capabilities || [],
            technical_foundation: {
                technologies: intelligence.technologies || [],
                features: intelligence.features || []
            },
            quick_insights: [
                {
                    icon: '📊',
                    metric: `${intelligence.summary_quality_score}/10`,
                    label: 'Intelligence Quality',
                    description: 'Based on data source availability and completeness'
                },
                ...(intelligence.recent_velocity ? [{
                    icon: '🚀',
                    metric: intelligence.recent_velocity.commits_per_day.toFixed(1),
                    label: 'Commits/Day',
                    description: 'Recent development velocity'
                }] : []),
                ...(intelligence.primary_domains ? [{
                    icon: '🏢',
                    metric: intelligence.primary_domains.length,
                    label: 'Business Domains',
                    description: 'Identified domain areas'
                }] : [])
            ]
        }
    };
}

/**
 * Check if executive intelligence is available
 * @param {string} repoSource - Data source
 * @returns {Promise<boolean>} True if intelligence data exists
 */
export async function hasExecutiveIntelligence(repoSource) {
    try {
        const dataPath = `data/repos/${repoSource}/executive-intelligence.json`;
        const response = await fetch(dataPath, { method: 'HEAD' });
        return response.ok;
    } catch {
        return false;
    }
}
